//! Which clipboard changes must never be recorded.

/// Markers apps put on the pasteboard to say "do not keep this"
/// (see nspasteboard.org), plus a few app-specific ones.
const PRIVATE_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "Pasteboard generator type",
    "net.antelle.keeweb",
];

/// Password managers whose copies are skipped even without a marker.
const PASSWORD_MANAGERS: &[&str] = &[
    "com.1password.1password",
    "com.agilebits.onepassword7",
    "com.agilebits.onepassword-osx",
    "com.apple.keychainaccess",
    "com.apple.Passwords",
    "com.bitwarden.desktop",
    "com.dashlane.dashlanephonefinal",
    "com.keepersecurity.passwordmanager",
    "com.lastpass.LastPass",
    "com.markmcguill.strongbox.mac",
    "com.nordpass.macos.NordPass",
    "com.roboform.mac",
    "in.sinew.Enpass-Desktop",
    "org.keepassxc.keepassxc",
];

/// Whether a clipboard change should go into the history. `types` are the
/// pasteboard types, `source` the bundle id of the app that was frontmost,
/// `ignored` the user's own list of bundle ids.
pub fn should_record(types: &[String], source: Option<&str>, ignored: &[String]) -> bool {
    let private = types.iter().any(|t| PRIVATE_TYPES.contains(&t.as_str()));
    let blocked_source = source.is_some_and(|source| {
        PASSWORD_MANAGERS.contains(&source) || ignored.iter().any(|app| app == source)
    });
    !private && !blocked_source
}

#[cfg(test)]
mod tests {
    use super::*;

    fn types(list: &[&str]) -> Vec<String> {
        list.iter().map(|t| t.to_string()).collect()
    }

    #[test]
    fn ordinary_copies_are_recorded() {
        let plain = types(&["public.utf8-plain-text"]);
        assert!(should_record(&plain, Some("com.apple.Safari"), &[]));
        assert!(should_record(&plain, None, &[]));
    }

    #[test]
    fn concealed_and_transient_markers_are_skipped() {
        for marker in [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.TransientType",
        ] {
            let t = types(&["public.utf8-plain-text", marker]);
            assert!(!should_record(&t, Some("com.apple.Safari"), &[]));
        }
    }

    #[test]
    fn password_managers_and_ignored_apps_are_skipped() {
        let plain = types(&["public.utf8-plain-text"]);
        assert!(!should_record(&plain, Some("com.bitwarden.desktop"), &[]));
        assert!(!should_record(&plain, Some("com.apple.Passwords"), &[]));
        let ignored = vec!["com.example.secret".to_owned()];
        assert!(!should_record(&plain, Some("com.example.secret"), &ignored));
        assert!(should_record(&plain, Some("com.example.other"), &ignored));
    }
}
